command:
// Sets Stellar Attunement to Graviton on the controlled token or your assigned character.
// Part of Outrider's Mods - 0utrider.github.io/pathfinder
const api = game.modules.get("outrider-stellar-attunement")?.api;
if (!api) return ui.notifications.warn("Outrider's Stellar Attunement is not active.");
await api.setAttunement(null, "graviton");
